{
  "objective": "Using validation-only evidence, produce bounded research and risk directives for the frozen Phase 12 protocol. Never access test metrics.",
  "mode": "dry_run",
  "rationale": "Dataset manifest validated (formal_v3, 80 symbols, 73193 rows, quality_valid=true). Bounded research plan constructed under validation-only constraints; all steps designed to avoid test metrics and operate within dry-run guardrails.",
  "steps": [
    {
      "id": "inspect_manifest",
      "action": "inspect_dataset",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": [],
      "expected_artifacts": ["dataset_summary"]
    },
    {
      "id": "validate_dataset",
      "action": "validate_dataset",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["inspect_manifest"],
      "expected_artifacts": ["validation_report"]
    },
    {
      "id": "list_markets",
      "action": "list_markets",
      "arguments": {},
      "depends_on": ["validate_dataset"],
      "expected_artifacts": ["market_list"]
    },
    {
      "id": "list_symbols",
      "action": "list_symbols",
      "arguments": {
        "markets": ["CN", "HK", "JP", "US"]
      },
      "depends_on": ["list_markets"],
      "expected_artifacts": ["symbol_list"]
    },
    {
      "id": "create_split",
      "action": "create_split",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json",
        "split_ratios": {
          "train": 0.7,
          "val": 0.3
        }
      },
      "depends_on": ["list_symbols"],
      "expected_artifacts": ["split_indices"]
    },
    {
      "id": "validate_config",
      "action": "validate_experiment_config",
      "arguments": {
        "config_path": "configs/phase12_rl_config.yaml"
      },
      "depends_on": ["create_split"],
      "expected_artifacts": ["config_validation"]
    },
    {
      "id": "estimate_budget",
      "action": "estimate_compute_budget",
      "arguments": {
        "config_path": "configs/phase12_rl_config.yaml",
        "dataset_size": 73193,
        "num_symbols": 80
      },
      "depends_on": ["validate_config"],
      "expected_artifacts": ["budget_estimate"]
    },
    {
      "id": "train_rl",
      "action": "train_rl",
      "arguments": {
        "config_path": "configs/phase12_rl_config.yaml",
        "train_indices": "split_indices[train]"
      },
      "depends_on": ["estimate_budget"],
      "expected_artifacts": ["checkpoint"]
    },
    {
      "id": "tune_rl",
      "action": "tune_rl",
      "arguments": {
        "base_config": "configs/phase12_rl_config.yaml",
        "hyperparameter_space": "configs/phase12_hparam_space.json",
        "metric": "val_sharpe",
        "max_trials": 20
      },
      "depends_on": ["train_rl"],
      "expected_artifacts": ["best_config", "tuning_log"]
    },
    {
      "id": "evaluate_checkpoint",
      "action": "evaluate_checkpoint",
      "arguments": {
        "checkpoint_path": "checkpoint_best",
        "val_indices": "split_indices[val]",
        "metrics": ["sharpe", "max_drawdown", "win_rate"]
      },
      "depends_on": ["train_rl", "tune_rl"],
      "expected_artifacts": ["evaluation_metrics"]
    },
    {
      "id": "compare_runs",
      "action": "compare_runs",
      "arguments": {
        "run_ids": ["phase12_baseline", "phase12_tuned"],
        "metrics": ["sharpe", "max_drawdown", "win_rate"]
      },
      "depends_on": ["evaluate_checkpoint"],
      "expected_artifacts": ["comparison_report"]
    },
    {
      "id": "generate_report",
      "action": "generate_report",
      "arguments": {
        "template": "templates/phase12_risk_report.md",
        "artifacts": ["comparison_report", "budget_estimate", "config_validation"]
      },
      "depends_on": ["compare_runs"],
      "expected_artifacts": ["final_report"]
    }
  ],
  "confidence": 0.85,
  "estimated_compute_units": 150.0,
  "safe_to_execute": false,
  "test_metrics_accessed": false,
  "validation_only": true
}
